package dev.hoi.client.map;

import com.google.gson.JsonParser;
import com.mojang.blaze3d.platform.InputConstants;
import dev.hoi.client.ClientCampaignHud;
import dev.hoi.client.screen.ScreenMapCursor;
import dev.hoi.client.ui.UiCommandLabels;
import dev.hoi.protocol.*;
import dev.hoi.protocol.ProtocolCommanderHud.*;
import java.nio.file.*;
import java.util.*;
import net.fabricmc.fabric.api.client.gametest.v1.context.ClientGameTestContext;
import net.minecraft.client.Minecraft;
import net.minecraft.client.input.*;

public final class MapCommanderTheaterCardsTest {
    private MapCommanderTheaterCardsTest() {}
    private static void accept(View source){var client=Minecraft.getInstance();MapCommanderHud.accept(new View(source.country(),client.level.dimension().identifier().toString(),source.branch(),source.cards(),source.wings(),true,source.theaters(),source.armyTheaters()));}
    private static void click(double x,double y,int button){var screen=Minecraft.getInstance().gui.screen();var event=new MouseButtonEvent(x,y,new MouseButtonInfo(button,0));if(!screen.mouseClicked(event,false))throw new AssertionError("Input not consumed");screen.mouseReleased(event);}
    private static void hit(String icon){var h=MapCommanderPanels.hits().stream().filter(v->v.icon().equals(icon)).findFirst().orElseThrow(()->new AssertionError(icon));click(h.x()+h.w()/2.,h.y()+h.h()/2.,InputConstants.MOUSE_BUTTON_LEFT);}
    private static List<MapCommanderHud.Box> attachments(){return MapCommanderHud.boxes().stream().filter(b->b.request()!=null&&b.request().mode()==Mode.AIR_ATTACH).toList();}
    private static MapCommanderHud.Box card(String id){return MapCommanderHud.boxes().stream().filter(b->b.request()!=null&&b.request().target().equals(id)).findFirst().orElseThrow();}
    private static void visible(Set<String> expected){var actual=MapCommanderHud.boxes().stream().filter(b->b.request()!=null&&Set.of(Mode.ASSIGN_ARMY,Mode.ASSIGN_GROUP_MARSHAL,Mode.NAVY_FLEET).contains(b.request().mode())).map(b->b.request().target()).collect(java.util.stream.Collectors.toSet());if(!actual.equals(expected))throw new AssertionError("Cards "+actual+" expected "+expected);}
    private static void context(){var client=Minecraft.getInstance();MapCommanderOrders.accept(new ProtocolCommanderOrders.Context(UUID.randomUUID().toString(),1,"KOR",client.level.dimension().identifier().toString(),""));}
    private static View syntheticRoles(View source,String... roles){var json=JsonParser.parseString(Snapshot.of(source).json()).getAsJsonObject();var wings=json.getAsJsonArray("wings");String army=source.armyTheaters().get(1).armies().getFirst();for(int i=0;i<wings.size();i++){var data=wings.get(i).getAsJsonObject().getAsJsonObject("data");data.addProperty("attachedArmy",i<roles.length&&MapCommanderHud.attachmentFrame(roles[i])>=0?army:"");if(i<roles.length)data.getAsJsonObject("air").getAsJsonObject("wing").addProperty("role",roles[i]);}return new Snapshot(json.toString()).view();}
    private static void drag(ClientGameTestContext game,View source,int[] size){
        var json=JsonParser.parseString(Snapshot.of(source).json()).getAsJsonObject();boolean navy=source.branch()==Mode.NAVY_HQ;var cards=json.getAsJsonArray("cards");
        if(!navy)for(var value:cards){var c=value.getAsJsonObject();if(c.get("role").getAsString().equals("ASSIGN_ARMY"))c.getAsJsonObject("panel").addProperty("parent","");}
        var fixture=new Snapshot(json.toString()).view();var theaters=fixture.branch()==Mode.AIR?fixture.armyTheaters():fixture.theaters();var theater=theaters.getFirst();var shown=navy?theater.fleets():theater.armies();var a=shown.getFirst();var b=shown.getLast();var selected=fixture.cards().stream().filter(c->c.id().equals(a)).findFirst().orElseThrow();var siblings=MapCommanderCardDrag.siblings(fixture,selected,"").stream().map(Card::id).toList();
        var commands=new ArrayList<ProtocolCommanderOrders.Command>();game.runOnClient(client->{MapCommanderHud.reset();MapUnitHud.reset();accept(fixture);MapCommanderOrders.commandObserver=commands::add;context();});game.waitTicks(2);
        double destination=game.computeOnClient(client->{var to=card(b);return to.x()+to.width()/2.+5;});
        game.runOnClient(client->{var from=card(a);var to=card(b);var event=new MouseButtonEvent(from.x()+from.width()/2.,from.y()+from.height()/2.,new MouseButtonInfo(InputConstants.MOUSE_BUTTON_LEFT,0));client.gui.screen().mouseClicked(event,false);client.gui.screen().mouseDragged(new MouseButtonEvent(to.x()+to.width()/2.+5,from.y()+from.height()/2.,new MouseButtonInfo(InputConstants.MOUSE_BUTTON_LEFT,0)),to.x()-from.x()+5,0);});game.waitTicks(2);game.takeScreenshot("hoi-theater-drag-synthetic-"+source.branch().name().toLowerCase(Locale.ROOT)+"-"+size[0]+"x"+size[1]+"-gui2");
        game.runOnClient(client->{var to=card(b);client.gui.screen().mouseReleased(new MouseButtonEvent(destination,to.y()+to.height()/2.,new MouseButtonInfo(InputConstants.MOUSE_BUTTON_LEFT,0)));if(commands.size()!=1||!commands.getFirst().action().equals("CARD_ORDER"))throw new AssertionError("Missing CARD_ORDER: "+commands);var order=commands.getFirst().selection();if(order.equals(siblings)||!new HashSet<>(order).equals(new HashSet<>(siblings)))throw new AssertionError("Drag must send a changed complete sibling list");for(int i=0;i<siblings.size();i++)if(!shown.contains(siblings.get(i))&&!order.get(i).equals(siblings.get(i)))throw new AssertionError("Hidden sibling moved");});
    }
    public static void run(ClientGameTestContext game,ProtocolMenuView menu,String directory)throws java.io.IOException{
        var army=new Snapshot(Files.readString(Path.of(directory,"kor-command-panel-army-two-theaters.json"))).view();var air=new Snapshot(Files.readString(Path.of(directory,"kor-command-panel-air-army-theaters.json"))).view();var navy=new Snapshot(Files.readString(Path.of(directory,"kor-command-panel-navy-theaters.json"))).view();
        for(int[] size:List.of(new int[]{2560,1440},new int[]{1280,720})){
            String suffix=size[0]+"x"+size[1]+"-gui2";var opens=new ArrayList<Open>();var first=army.theaters().getFirst();var second=army.theaters().get(1);String target=second.armies().getFirst();
            game.getInput().resizeWindow(size[0],size[1]);game.runOnClient(client->{client.options.guiScale().set(2);MapCommanderHud.reset();MapUnitHud.reset();ClientCampaignHud.accept(ProtocolHudPayloads.State.of("KOR",menu.hud()));MapCommanderHud.requestObserver=opens::add;MapCommanderOrders.selectionObserver=ignored->{};accept(army);});game.setScreen(ScreenMapCursor::new);game.getInput().setCursorPos(20,60);game.waitTicks(2);
            game.runOnClient(client->visible(Set.copyOf(first.groups())));game.takeScreenshot("hoi-army-theater-one-"+suffix);
            game.runOnClient(client->{var h=MapCommanderPanels.hits().stream().filter(v->v.icon().equals("theater_card")&&v.tip().equals(MapCommanderHud.cardTooltip(army.cards().stream().filter(c->c.id().equals(target)).findFirst().orElseThrow()))).findFirst().orElseThrow();var overlaps=MapCommanderPanels.hits().stream().filter(v->v.contains(h.x()+h.w()/2.,h.y()+h.h()/2.)).map(v->v.icon()+":"+v.tip()).toList();click(h.x()+h.w()/2.,h.y()+h.h()/2.,InputConstants.MOUSE_BUTTON_LEFT);if(!MapCommanderHud.theaters.selected(army).equals(second.id()))throw new AssertionError("Theater row selection failed: "+MapCommanderPanels.selectedCards()+" "+overlaps);});game.waitTicks(2);game.runOnClient(client->visible(Set.of(target)));game.takeScreenshot("hoi-army-theater-two-row-"+suffix);
            game.runOnClient(client->accept(air));game.waitTicks(2);game.runOnClient(client->{visible(Set.of(target));if(attachments().size()!=2)throw new AssertionError("Fighter and support must have separate boxes");if(MapCommanderHud.boxes().stream().anyMatch(b->b.tip().equals(UiCommandLabels.text("ATTACH_AIR_WING_DESC",""))))throw new AssertionError("Unselected view must not show plus");var boxes=attachments();var portrait=card(target);if(boxes.getFirst().x()!=portrait.x()+3||boxes.get(1).x()!=portrait.x()+15||boxes.stream().anyMatch(b->b.y()+b.height()!=portrait.y()-8))throw new AssertionError("Populated category slots must use fixed thirds immediately above stop/play");for(int i=0;i<2;i++){var wing=air.wings().get(i);var box=boxes.get(i);if(!box.tip().contains("§G"+wing.data().quantity()+"§!")||box.tip().contains("?G"))throw new AssertionError("Original quantity tooltip color codes must survive");if(!box.request().selection().equals(List.of("action/detach",wing.id()))||!box.tip().contains(wing.name())||box.tip().contains(air.wings().get(1-i).name()))throw new AssertionError("Category tooltip/request leaked wings");}});game.takeScreenshot("hoi-air-theater-two-categories-"+suffix);
            for(int i=0;i<2;i++){int category=i;var box=game.computeOnClient(client->attachments().get(category));game.getInput().setCursorPos((box.x()+box.width()/2.)*2,(box.y()+box.height()/2.)*2);game.waitTicks(2);game.takeScreenshot("hoi-air-category-tooltip-"+i+"-"+suffix);game.runOnClient(client->{click(box.x()+2,box.y()+2,InputConstants.MOUSE_BUTTON_RIGHT);if(opens.size()!=1||!opens.getFirst().equals(box.request()))throw new AssertionError("Category detach scope changed");opens.clear();click(box.x()+2,box.y()+2,InputConstants.MOUSE_BUTTON_LEFT);if(!MapCommanderPanels.attachmentWings().equals(List.of(air.wings().get(category).id())))throw new AssertionError("Category click must select only its wings");});game.waitTicks(2);}
            game.getInput().setCursorPos(20,60);game.takeScreenshot("hoi-air-theater-two-selected-"+suffix);
            game.runOnClient(client->{accept(army);});game.waitTicks(2);game.runOnClient(client->hit("theater_title/"+first.id()));game.waitTicks(2);game.runOnClient(client->accept(air));game.waitTicks(2);game.runOnClient(client->visible(Set.copyOf(first.groups())));game.takeScreenshot("hoi-air-theater-one-"+suffix);
            game.runOnClient(client->{MapUnitHud.replaceKeys(List.of(air.wings().getFirst().selectionKey()));MapCommanderPanels.mapSelectionChanged();});game.waitTicks(2);game.runOnClient(client->visible(Set.of(target)));game.takeScreenshot("hoi-air-map-selection-theater-two-"+suffix);
            for(int populated=0;populated<2;populated++){
                int count=populated;var partial=count==0?syntheticRoles(air):syntheticRoles(air,"FIGHTER");
                game.runOnClient(client->{accept(partial);MapCommanderHud.theaters.choose(partial,second.id());MapCommanderPanels.showWings(List.of(partial.wings().getFirst().id()));});game.waitTicks(2);
                game.runOnClient(client->{var plus=MapCommanderHud.boxes().stream().filter(b->b.tip().equals(UiCommandLabels.text("ATTACH_AIR_WING_DESC",""))).toList();var portrait=card(target);if(attachments().size()!=count||plus.size()!=1||plus.getFirst().x()!=portrait.x()+28||plus.getFirst().y()+plus.getFirst().height()!=portrait.y()-8)throw new AssertionError("Plus must occupy the fixed right third without painting empty categories");var box=plus.getFirst();click(box.x()+2,box.y()+2,InputConstants.MOUSE_BUTTON_LEFT);click(box.x()+2,box.y()+2,InputConstants.MOUSE_BUTTON_LEFT);if(opens.size()!=2||opens.stream().anyMatch(o->o.mode()!=Mode.AIR_ATTACH||!o.selection().equals(List.of("army/"+target,partial.wings().getFirst().id()))))throw new AssertionError("Plus must retain exact selected-wing attachment requests");opens.clear();if(count==0&&MapCommanderHud.clickAt(portrait.x()+5,box.y()+2,InputConstants.MOUSE_BUTTON_LEFT,false))throw new AssertionError("Undrawn empty thirds must not attach");});
                game.getInput().setCursorPos(20,60);game.takeScreenshot("hoi-air-"+(count==0?"empty":"one")+"-plus-"+suffix);
            }
            var synthetic=syntheticRoles(air,"FIGHTER","HEAVY_FIGHTER","CAS","TACTICAL_BOMBER","NAVAL_BOMBER","TRANSPORT","STRATEGIC_BOMBER","SCOUT");game.runOnClient(client->{accept(synthetic);MapCommanderHud.theaters.choose(synthetic,second.id());MapCommanderPanels.showWings(synthetic.wings().stream().limit(5).map(Member::id).toList());});game.waitTicks(2);game.runOnClient(client->{var counts=attachments().stream().map(b->b.request().selection().size()-1).toList();var plus=MapCommanderHud.boxes().stream().filter(b->b.tip().equals(UiCommandLabels.text("ATTACH_AIR_WING_DESC",""))).toList();if(plus.size()!=1||plus.getFirst().x()!=card(target).x()+28)throw new AssertionError("Populated categories must retain the fixed right plus slot");if(!counts.equals(List.of(2,3)))throw new AssertionError("Only fighter and support categories: "+counts);});game.takeScreenshot("hoi-air-all-roles-synthetic-"+suffix);
            for(int total:List.of(999,1000,1200,9999,10000,123,1234,12345)){
                var largeJson=JsonParser.parseString(Snapshot.of(synthetic).json()).getAsJsonObject();for(int i=0;i<2;i++)largeJson.getAsJsonArray("wings").get(i).getAsJsonObject().getAsJsonObject("data").addProperty("quantity",i==0?total-total/2:total/2);var large=new Snapshot(largeJson.toString()).view();game.runOnClient(client->accept(large));game.waitTicks(2);game.runOnClient(client->{var fighters=large.wings().stream().filter(w->target.equals(w.data().attachedArmy())&&MapCommanderHud.attachmentFrame(MapCommanderPanels.airRole(w))==0).toList();if(fighters.stream().mapToInt(w->w.data().quantity()).sum()!=total||attachments().getFirst().request().selection().size()!=3||!attachments().getFirst().tip().contains("§G"+(total-total/2)+"§!"))throw new AssertionError("Display truncation must preserve source quantities, tooltip and both fighter wings");});game.takeScreenshot("hoi-air-count-"+total+"-synthetic-"+suffix);
            }
            game.runOnClient(client->accept(synthetic));game.waitTicks(2);
            for(String role:List.of("TRANSPORT","STRATEGIC_BOMBER","SCOUT")){game.runOnClient(client->MapCommanderPanels.showWings(synthetic.wings().stream().filter(w->role.equals(MapCommanderPanels.airRole(w))||"FIGHTER".equals(MapCommanderPanels.airRole(w))).map(Member::id).toList()));game.waitTicks(2);var disabled=game.computeOnClient(client->MapCommanderHud.boxes().stream().filter(b->b.tip().equals(UiCommandLabels.text("CANNOT_ATTACH_AIR_WING_DESC",""))).findFirst().orElseThrow());game.getInput().setCursorPos((disabled.x()+4)*2,(disabled.y()+4)*2);game.waitTicks(2);game.takeScreenshot("hoi-air-disabled-"+role.toLowerCase(Locale.ROOT)+"-"+suffix);game.runOnClient(client->{click(disabled.x()+2,disabled.y()+2,InputConstants.MOUSE_BUTTON_LEFT);click(disabled.x()+2,disabled.y()+2,InputConstants.MOUSE_BUTTON_LEFT);var box=card(target);click(box.x()+box.width()/2.,box.y()+box.height()/2.,InputConstants.MOUSE_BUTTON_RIGHT);if(!opens.isEmpty())throw new AssertionError("Ineligible mixed selection sent attachment");});}
            game.getInput().setCursorPos(20,60);for(var fixture:List.of(army,air,navy))drag(game,fixture,size);
            game.runOnClient(client->{MapCommanderHud.requestObserver=null;MapCommanderOrders.commandObserver=null;MapCommanderOrders.selectionObserver=null;MapCommanderHud.reset();MapUnitHud.reset();});
        }
    }
}
